const KEY='form_fitness_v2';let state;try{state=JSON.parse(localStorage.getItem(KEY))||{}}catch{state={}};state.checks ||= {};state.notes ||= {};state.start ||= new Date().toISOString().slice(0,10);state.mealNotes ||= {};state.workoutNotes ||= {};state.recipeNotes ||= {};state.config ||= {};state.updated ||= new Date().toISOString();
let page='dashboard',month=1,day=0,week=1,token=null,account=null,syncTimer=null,syncMessage='Saved locally',refreshToken=null,expiresAt=0,refreshPromise=null;
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navs=[['dashboard','⌂','Dashboard'],['workouts','◇','Workouts'],['meals','▤','Meal prep'],['grocery','▣','Grocery list'],['planner','▦','Year planner'],['notes','✎','My notes'],['fbi','◈','FBLE prep'],['settings','⚙','Settings']];
function localSave(){state.updated=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(state));syncMessage=token?'Sync pending':'Saved locally';updateSync();if(token){clearTimeout(syncTimer);syncTimer=setTimeout(pushCloud,900)}}
function updateSync(){const e=$('#syncStatus');if(e)e.textContent=syncMessage}
function setCheck(key,val){state.checks[key]=val;localSave();render()}
function checked(key){return !!state.checks[key]}
function checkHTML(key,label,extra=''){return `<label class="check"><input type="checkbox" ${checked(key)?'checked':''} onchange="setCheck('${key}',this.checked)"><span>${label}${extra?`<div class="muted">${extra}</div>`:''}</span></label>`}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'instant'})}
function setMonth(m){month=m;render()};function setDay(d){day=d;render()};function setWeek(w){week=w;render()}
function getDayOfYear(){let n=Math.floor((new Date().setHours(0,0,0,0)-new Date(state.start+'T00:00:00'))/86400000);return Math.max(0,n)}
function current(){const n=getDayOfYear();return {m:Math.min(12,Math.floor(n/30.4375)+1),w:Math.min(4,Math.floor((n%30.4375)/7.61)+1)}}
function section(title,sub=''){return `<div class="eyebrow">${esc(sub)}</div><h2 class="smallhead">${esc(title)}</h2>`}
function render(){const labels={dashboard:'Your dashboard.',workouts:'Move with purpose.',fbi:'Build your future.',meals:'Nourish your day.',grocery:'Your grocery list.',notes:'Your notes.',planner:'Your year in motion.',settings:'Make it yours.'};$('#pageTitle').textContent=labels[page];$('#breadcrumb').textContent='FORM. / '+page.toUpperCase();$('#nav').innerHTML=navs.map(([id,ic,label])=>`<button class="${page===id?'active':''}" onclick="go('${id}')">${ic} &nbsp; ${label}</button>`).join('');$('#mobileNav').innerHTML=navs.map(([id,ic,label])=>`<button class="${page===id?'active':''}" onclick="go('${id}')"><span>${ic}</span>${label}</button>`).join('');$('#view').innerHTML=({dashboard:dashboard,workouts:workouts,fbi:fbiPathway,meals:meals,grocery:groceryPage,notes:notesPage,planner:planner,settings:settings})[page]();updateSync()}
function fbiPathway(){return `<p class="sub">Explore a future FBI career while building healthy, age-appropriate fitness and academic habits. This is a preparation roadmap, not an official FBI training program or fitness test.</p><div class="grid"><div class="card wide">${section('Your career pathway','CAREER EXPLORATION')}<h3>Build a strong foundation</h3><p class="sub">The FBI has different career paths, including special agent, intelligence analyst, technology, and professional support roles. Requirements vary by role and may change. Use official FBI Jobs information when you are ready to apply.</p><a class="btn" href="https://fbijobs.gov/" target="_blank" rel="noopener noreferrer">Explore official FBI careers ↗</a></div><div class="card">${section('Fitness foundations','MOVE SAFELY')}<p class="sub">Practice comfortable push-up variations, squats, core stability, walking and easy jogging. Focus on technique, gradual progress, and recovery rather than speed or appearance.</p>${checkHTML('fbi-fitness-week','Practiced comfortable movement this week')}${checkHTML('fbi-recovery-week','Made time for recovery')}</div><div class="card">${section('Learning foundations','SKILLS THAT MATTER')}<p class="sub">Keep learning writing, reading, math, science, technology, and critical thinking. Communication, teamwork, and responsible decision-making are useful across many FBI roles.</p>${checkHTML('fbi-learning-week','Practiced a school or learning goal')}${checkHTML('fbi-teamwork-week','Practiced communication or teamwork')}</div><div class="card wide">${section('Fuel and recovery','SUPPORT YOUR GROWTH')}<p class="sub">Eat balanced meals and snacks, drink water, and get adequate sleep. Your meal-prep plan supports everyday energy and strength; you do not need to restrict food or pursue visible abs to be fit.</p><button class="btn" onclick="go('meals')">Open meal prep →</button> <button class="btn" onclick="go('workouts')">Open workouts →</button></div><div class="card wide">${section('About FBI fitness testing','FOR THE FUTURE')}<p class="sub">Some FBI positions have formal physical fitness assessments for adult applicants. FORM. does not prescribe adult test targets or intense timed testing for teens. Review current official requirements when you are eligible, and ask a qualified coach or trusted adult for exercise guidance.</p><a href="https://fbijobs.gov/" target="_blank" rel="noopener noreferrer">Official FBI Jobs website ↗</a></div></div>`}
function dashboard(){const hour=new Date().getHours();const greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';let c=current(),n=Object.values(state.checks).filter(Boolean).length;let d=(new Date().getDay()+6)%7;return `<p class="form-greeting">${greeting}, Navi. Welcome to FORM.</p><p class="sub">Build strength, running confidence, and nourishing routines at your own pace.</p><div class="grid"><div class="card dark"><div class="eyebrow">CURRENT TRAINING FOCUS</div><div class="stat">MONTH ${c.m.toString().padStart(2,'0')}</div><h3>${MONTHS[c.m-1][0]}</h3><p class="sub">${MONTHS[c.m-1][1]}</p><button class="btn inverse" onclick="month=${c.m};go('planner')">View yearly plan →</button></div><div class="card"><div class="eyebrow">YOUR RECORD</div><div class="stat">${n}</div><p class="sub">Checklist items marked complete. Rest and flexibility are part of progress.</p><div class="progress"><div style="width:${Math.min(100,n/20*100)}%"></div></div><p class="note">This bar represents the first 20 checkmarks, not a fitness score.</p></div><div class="card">${section('Today’s movement',DAYS[d])}<h3>${SCHEDULE[d][0]}</h3><p class="muted">${SCHEDULE[d][1]}</p>${EXERCISES[d].slice(0,3).map((x,i)=>checkHTML(`daily-${today()}-${d}-${i}`,esc(x[0]),esc(x[1]))).join('')}<button class="btn" style="margin-top:14px" onclick="day=${d};go('workouts')">See full workout →</button></div><div class="card">${section('Today’s meals','TODAY’S PLAN')}${MEAL_DAYS[d].map(i=>`<div class="row" style="padding:9px 0;border-bottom:1px solid #eee"><b>${esc(MEALS[i].name)}</b><span class="muted">${MEALS[i].type}</span></div>`).join('')}<p class="note">Eat enough to support your energy, growth, and recovery. Adjust meals to your hunger.</p><button class="btn" onclick="day=${d};go('meals')">Open meal prep →</button></div></div>`}
function today(){return new Date().toLocaleDateString('en-CA')}
function dayTabs(){return `<div class="tabs">${DAYS.map((d,i)=>`<button class="${day===i?'selected':''}" onclick="setDay(${i})">${d.slice(0,3)}</button>`).join('')}</div>`}
function exerciseArt(name){let type=/walk|jog/i.test(name)?'run':/squat|lunge|calf/i.test(name)?'stand':/plank|push|bridge|dead bug|bird dog/i.test(name)?'floor':'stretch';let paths={run:'<circle cx="54" cy="19" r="9"/><path d="M48 32l-13 18 20 9 12-13M49 33l20 9 13-7M55 59l-9 22M55 59l24 17"/>',stand:'<circle cx="50" cy="18" r="9"/><path d="M50 28l-6 30 22 13M44 58L27 77M47 39L27 48M49 39l20 8"/>',floor:'<circle cx="76" cy="42" r="8"/><path d="M68 45L45 54 25 51M45 54l-8 20M45 54l23 20M20 80h70"/>',stretch:'<circle cx="51" cy="20" r="9"/><path d="M51 31v31M51 39L27 24M51 39l23-15M51 62L35 83M51 62l17 21"/>'};return `<svg viewBox="0 0 100 100" fill="none" stroke="#111" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" role="img" aria-label="Simplified exercise illustration"><path d="${''}"/>${paths[type]}</svg>`}
function exerciseVisual(name){let icon=/walk|jog/i.test(name)?'🚶':/squat|lunge|calf/i.test(name)?'🦵':/plank|push|bridge|dead bug|bird dog/i.test(name)?'💪':'🧘';return `<div class="exercise-visual"><span>${icon}</span><small>${esc(name)}</small></div>`}
function workouts(){return `<p class="sub">Your source plan uses this weekly routine as its starting checklist. The monthly roadmap gives focus areas, not new exercise prescriptions for every week. For Weeks 2–4, repeat the routine; add a few repetitions or slightly longer jogging intervals only if you feel ready. You can repeat any week. Warm up, rest between sets, and prioritize comfortable form.</p>${dayTabs()}<div class="grid"><div class="card wide">${section(SCHEDULE[day][0],`${DAYS[day].toUpperCase()} • ${SCHEDULE[day][1]}`)}${EXERCISES[day].map((x,i)=>`<div class="exercise"><div class="illustration">${exerciseVisual(x[0])}</div><div><h4>${esc(x[0])}</h4><p class="muted"><b>${esc(x[1])}</b></p><p class="note">${esc(x[2])}</p>${movementGuide(x[0])}${checkHTML(`daily-${today()}-${day}-${i}`,'Completed today')}<div class="field"><label>Exercise notes</label><textarea oninput="saveWorkoutNote('${day}-${i}',this.value)" placeholder="Form cues, progress, or reflections">${esc(state.workoutNotes[day+'-'+i]||'')}</textarea></div></div></div>`).join('')}</div><div class="card wide"><b>Training safety</b><p class="sub">Warm up first; rest about 45–90 seconds between sets. Progress gradually, repeat weeks as needed, and stop for pain, dizziness, or unusual shortness of breath. Recovery matters.</p><p class="note">Every exercise includes offline written instructions. Only exercises with checked direct YouTube video pages show a video button; other exercises do not link to search results. Ask a qualified coach or trusted adult for form guidance when needed.</p></div></div>`}

const APPEARANCE_KEY='form-appearance-v1';
function appearanceChoice(){return localStorage.getItem(APPEARANCE_KEY)||state.appearance||'light'}
function applyAppearance(){const choice=appearanceChoice();document.documentElement.dataset.theme=choice==='automatic'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):choice}
function setAppearance(value){if(!['light','dark','automatic'].includes(value))return;localStorage.setItem(APPEARANCE_KEY,value);state.appearance=value;localSave();applyAppearance();render()}
if(window.matchMedia){matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(appearanceChoice()==='automatic')applyAppearance()})}
applyAppearance();
const groceryIcons={'oats':'🌾','yogurt':'🥣','banana':'🍌','milk':'🥛','tofu':'🥡','brown rice':'🍚','broccoli':'🥦','lentils':'🫘','sweet potato':'🍠','spinach':'🥬','soy chunks':'🫘','black beans':'🫘','tomatoes':'🍅','eggs':'🥚','onion':'🧅','soy sauce':'🧂','cooking oil':'🫒','spices':'🌶️','orange':'🍊','strawberries':'🍓','peanut butter':'🥜'};
function recipeDetails(i){const r=RECIPES[i];return `<details class="recipe-details"><summary>Full recipe · ${r.minutes} min · ${r.servings} serving${r.servings>1?'s':''}</summary><h4>Ingredients (for ${r.servings} servings)</h4><ul>${r.ingredients.map(x=>`<li>${esc(x.name)} — ${x.amount} ${x.unit==='count'?'egg(s)':x.unit==='amount'?'':'g'}</li>`).join('')}</ul><h4>Directions</h4><ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="note"><b>Storage:</b> ${esc(r.storage)} <b>Freezer plan:</b> ${esc(r.freezer)} Shopping totals cover whole recipe batches for the seven-day schedule; amounts are weighed before cooking unless noted. Portions are flexible; add food or snacks as needed.</p></details>`}
function funRecipeDetails(i){const r=FUN_RECIPES[i];return `<details class="recipe-details"><summary>Full featured recipe · ${r.minutes} min · ${r.servings} servings</summary><h4>Ingredients</h4><ul>${r.ingredients.map(x=>`<li>${esc(x.name)} — ${esc(x.amount)}${x.unit==='g'?' g':''}</li>`).join('')}</ul><h4>Directions</h4><ol>${r.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="note"><b>Storage:</b> ${esc(r.storage)} Adjust portions to appetite. Some packaged ingredients and cheeses may contain animal-derived ingredients, so check labels.</p></details>`}
const VIDEO_GUIDES={
  'Squats':{url:'https://www.youtube.com/watch?v=Uv_DKDl7EjA',title:'Squat University — squat form checklist (includes barbell discussion)'},
  'Glute bridges':{url:'https://www.youtube.com/watch?v=RvcX9GW1mEk&t=560s',title:'Physiotherapy guide — classic glute bridge section'},
  'Bird dogs':{url:'https://www.youtube.com/watch?v=ZdAHe9_HeEw',title:'NASM — bird dog proper form and technique'}
};
const MOVEMENT_STEPS={
 'Wall / knee push-ups':['Place your hands on a sturdy wall at chest height, or use a comfortable knee-supported floor variation.','Keep your head, shoulders and hips in a steady line.','Bend elbows to lower your chest slowly.','Press back to your starting position; breathe naturally.'],
 'Comfortable push-ups':['Choose wall, knee-supported, or floor push-ups based on comfort.','Set hands under or a little wider than shoulders and keep your trunk steady.','Bend elbows and lower slowly without dropping hips.','Press back up smoothly.'],
 'Wall slides':['Stand with your back close to a wall and relax your shoulders.','Bend elbows and place forearms near the wall as comfortable.','Slide arms upward without shrugging or arching your back.','Return slowly.'],
 'Plank':['Place forearms on a mat with elbows below shoulders.','Extend legs or rest knees on the floor.','Keep your body steady and breathe comfortably.','Lower and rest when your form changes.'],
 'Bird dogs':['Start on hands and knees, with hands under shoulders.','Reach one arm forward and the opposite leg back without twisting.','Pause briefly while breathing.','Return and alternate sides.'],
 'Dead bugs':['Lie on your back, arms toward the ceiling and knees bent above hips.','Gently brace your middle while breathing.','Slowly extend one arm and the opposite leg only as far as you can stay steady.','Return and alternate sides.'],
 'Walk–jog intervals':['Begin with an easy five-minute walk.','Alternate a comfortable one-minute jog and two-minute walk for five rounds.','Walk slowly to cool down.','Choose walking throughout if that feels better.'],
 'Squats':['Stand with feet roughly shoulder-width apart.','Bend hips and knees as though sitting into a chair, keeping feet grounded.','Lower only as far as feels comfortable.','Push through your feet to stand tall.'],
 'Reverse lunges':['Stand tall with feet hip-width apart; hold a stable support if needed.','Step one foot backward and bend both knees comfortably.','Keep your front foot planted and trunk steady.','Step forward to stand, then switch sides.'],
 'Glute bridges':['Lie on your back with knees bent and feet flat.','Keep feet about hip-width apart and arms relaxed.','Press through feet to lift hips until shoulders, hips and knees form a comfortable line.','Lower slowly without arching your lower back.'],
 'Calf raises':['Stand beside a wall or chair for balance.','Place feet flat and rise onto the balls of your feet.','Pause briefly without leaning forward.','Lower heels slowly.'],
 'Side plank':['Lie on one side with forearm under shoulder.','Keep knees bent for an easier version or legs straight if comfortable.','Lift hips gently and keep shoulders stacked.','Breathe and lower with control; switch sides.'],
 'Easy walk + gentle mobility':['Choose a relaxed walking pace or gentle mobility.','Move joints through comfortable ranges without bouncing.','Take breaks whenever needed.','Rest instead if that feels better.'],
 'Prone Y–T raises':['Lie face down on a mat with forehead supported comfortably.','Reach arms into a Y shape and gently lift a small amount.','Lower, then move arms into a T shape.','Lift and lower gently without straining neck or back.'],
 'Rest and recovery':['No exercise is required today.','Take a break, relax, or enjoy gentle movement if you want.','Resume when you feel ready.']
};
function movementGuide(name){const steps=MOVEMENT_STEPS[name]||['Set up comfortably.','Move with control.','Return slowly.'];const vid=VIDEO_GUIDES[name];return `<details class="movement-steps"><summary>How to do it · step by step</summary><ol>${steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="note"><b>Form reminder:</b> Breathe naturally, use a comfortable range, and stop if you feel pain or dizziness.</p></details>${vid?`<a class="demo-link" href="${vid.url}" target="_blank" rel="noopener noreferrer" aria-label="Watch ${esc(name)} tutorial on YouTube">▶ Watch direct YouTube tutorial ↗</a><p class="note">${esc(vid.title)}</p>`:'<p class="note">A direct tutorial has not been verified for this exercise yet. Follow the written steps above.</p>'}`}

const INGREDIENT_PHOTOS={"oats": "photo-1517673400267-0251440c45dc", "yogurt": "photo-1488477181946-6428a0291777", "banana": "photo-1571771894821-ce9b6c11b08e", "milk": "photo-1550583724-b2692b85b150", "tofu": "photo-1546069901-ba9599a7e63c", "brown rice": "photo-1512058564366-18510be2db19", "broccoli": "photo-1459411621453-7b03977f4bfc", "lentils": "photo-1515543904379-3d757afe72e4", "sweet potato": "photo-1518977676601-b53f82aba655", "spinach": "photo-1576045057995-568f588f82fb", "soy chunks": "photo-1546069901-ba9599a7e63c", "black beans": "photo-1515543904379-3d757afe72e4", "tomatoes": "photo-1546470427-e5b89b8b0b9e", "eggs": "photo-1506976785307-8732e854ad03", "onion": "photo-1508747703725-719777637510", "soy sauce": "photo-1472396961693-142e6e269027", "cooking oil": "photo-1474979266404-7eaacbcd87c5", "spices": "photo-1509358271058-acd22cc93898"};
function groceryCard(g,i){const key=`grocery-${current().m}-${current().w}-${i}`;return `<div class="grocery-item">${INGREDIENT_PHOTOS[g.search]?`<div class="grocery-photo"><img src="https://images.unsplash.com/${INGREDIENT_PHOTOS[g.search]}?w=160&h=160&fit=crop&auto=format" alt="Ingredient illustration" loading="lazy" onerror="this.parentElement.style.display='none'"></div>`:''}<label class="grocery-label"><input type="checkbox" ${checked(key)?'checked':''} onchange="setCheck('${key}',this.checked)"><span><b>${esc(g.name)}</b><small>${esc(g.brand.replace(/store-brand/gi,'store brand').replace(/^\s*or\s+/i,''))}</small><small><b>${g.snack?'Snack plan':'Recipe total'}:</b> ${g.required} ${g.snack?(g.name==='Orange'?'oranges':'g'):(g.name==='Eggs'?'eggs':'g')} · <b>Buy:</b> ${esc(g.quantity)}</small>${g.optional?'<small>Optional: use water in oats instead.</small>':''}${g.pantry?'<small>Check your pantry before buying.</small>':''}</span></label><span class="price">~$${g.price.toFixed(2)}</span></div>`}
function groceryList(){const sum=SHOPPING.reduce((a,g)=>a+g.price,0);const core=SHOPPING.filter(g=>!g.optional&&!g.pantry).reduce((a,g)=>a+g.price,0);return `<p class="note"><b>Recipe-to-cart match:</b> Main recipe totals cover the seven-day schedule: 7 breakfasts, 7 lunches and 7 dinners. Snack purchases are separate suggestions for 7 days and are not part of the cooked-recipe totals. Each recipe is made in whole batches (rounding up when a recipe serves 2 or 3), so some cooked servings remain for later. Ingredient amounts are weighed before cooking, except drained beans. <b>Recipe total</b> is what those batches require; <b>Buy</b> is a package or bulk quantity that covers it. You can use food already in your pantry.</p>${SHOPPING.map(groceryCard).join('')}<p class="note"><b>Estimated essentials:</b> ~$${core.toFixed(2)}. <b>Estimated all items including pantry restocks and optional milk:</b> ~$${sum.toFixed(2)}. Prices are illustrative, not current store prices. Bananas, onions and drained canned beans vary in usable weight: weigh them at home and buy a little extra if needed. Optional strawberries and peanut butter are not required to complete the cooked meals. Fresh oranges are included as a vitamin C-rich snack; eat other snacks according to appetite. The optional monthly featured meal is <b>not</b> included in these weekly totals; shop for its recipe separately. Photos illustrate ingredients, not verified brand packaging. This is a shopping budget, never a limit on food portions.</p>`}
function saveRecipeNote(i,v){state.recipeNotes[i]=v;localSave()}
function saveWorkoutNote(k,v){state.workoutNotes[k]=v;localSave()}
function groceryPage(){return `<p class="sub">A dedicated shopping checklist for your weekly recipe batches and flexible snacks. Quantities for cooking use grams; quantities to buy use packages, pounds, ounces or counts. Featured monthly meals are shopped separately.</p><div class="card">${section('Weekly grocery checklist','SHOP ONCE · PREP YOUR WEEK')}${groceryList()}</div>`}
function notesPage(){const recipeEntries=Object.entries(state.recipeNotes).filter(([k,v])=>String(v).trim());const workoutEntries=Object.entries(state.workoutNotes).filter(([k,v])=>String(v).trim());const journalEntries=Object.entries(state.mealNotes).filter(([k,v])=>String(v).trim());const planEntries=Object.entries(state.notes).filter(([k,v])=>String(v).trim());return `<p class="sub">Your private reflections, gathered in one place. Edit an existing note or add a new one from a meal or workout. Notes stay in your saved progress and backups.</p><div class="grid"><div class="card wide">${section('Meal notes',recipeEntries.length+' RECIPES')}${recipeEntries.length?recipeEntries.map(([k,v])=>`<div class="field"><label>${esc(MEALS[Number(k)]?.name||'Meal')}</label><textarea oninput="saveRecipeNote(${Number(k)},this.value)">${esc(v)}</textarea></div>`).join(''):'<p class="muted">No recipe notes yet. Open Meal prep to write one.</p>'}<button class="btn" onclick="go('meals')">Add a meal note →</button></div><div class="card wide">${section('Workout notes',workoutEntries.length+' EXERCISES')}${workoutEntries.length?workoutEntries.map(([k,v])=>{const [d,i]=k.split('-').map(Number);return `<div class="field"><label>${esc(DAYS[d]||'Workout')} · ${esc(EXERCISES[d]?.[i]?.[0]||'Exercise')}</label><textarea oninput="saveWorkoutNote('${esc(k)}',this.value)">${esc(v)}</textarea></div>`}).join(''):'<p class="muted">No workout notes yet. Open Workouts to write one.</p>'}<button class="btn" onclick="go('workouts')">Add a workout note →</button></div><div class="card wide">${section('Food journal',journalEntries.length+' ENTRIES')}${journalEntries.length?journalEntries.map(([k,v])=>`<div class="field"><label>${esc(k)}</label><textarea oninput="saveJournalEntry('${esc(k)}',this.value)">${esc(v)}</textarea></div>`).join(''):'<p class="muted">No food journal entries yet.</p>'}</div><div class="card wide">${section('Year planner reflections',planEntries.length+' ENTRIES')}${planEntries.length?planEntries.map(([k,v])=>`<div class="field"><label>${esc(k)}</label><textarea oninput="saveNote('${esc(k)}',this.value)">${esc(v)}</textarea></div>`).join(''):'<p class="muted">No planner reflections yet.</p>'}<button class="btn" onclick="go('planner')">Open year planner →</button></div></div>`}
function saveJournalEntry(k,v){state.mealNotes[k]=v;localSave()}
function meals(){let featured=FUN_MEALS[current().m-1];return `<p class="sub">Flexible meal prep: recipes use grams, shopping uses pounds/ounces/counts. Make the listed batch, divide into portions, and freeze suitable cooked components. Use freezer-safe containers or tightly wrapped freezer-safe foil; label each with the meal and date. Reheat until steaming hot (165°F/74°C for leftovers). Never reheat food in foil in a microwave.</p>${dayTabs()}<div class="grid">${MEAL_DAYS[day].map(i=>{let m=MEALS[i];return `<div class="card meal-card"><img class="meal-img" src="${m.img}" alt="Meal inspiration" loading="lazy" onerror="this.style.display='none'"><div class="eyebrow">${m.type}</div><h3>${esc(m.name)}</h3>${recipeDetails(i)}${checkHTML(`meal-${today()}-${day}-${i}`,'Meal prepared or enjoyed')}<div class="field"><label>My notes for ${esc(m.name)}</label><textarea oninput="saveRecipeNote(${i},this.value)" placeholder="How did it taste? What would you change?">${esc(state.recipeNotes[i]||'')}</textarea></div></div>`}).join('')}<div class="card wide">${section('Snacks & vitamin C','FLEXIBLE · YEAR-ROUND')}<p class="sub">One easy vitamin C-rich option is an orange with a meal or as a snack. Vitamin C helps absorb iron from beans and lentils. Choose other fruit when it is cheaper or preferred; frozen strawberries work well in yogurt or smoothies. For more filling snacks, pair fruit with peanut butter, cheese, eggs, or yogurt already in your plan. These are ideas, not a limit on how much to eat.</p><p class="note"><b>Weekly shopping guide:</b> 7 oranges; optional 280 g frozen strawberries (40 g × 7) and 105 g peanut butter (15 g × 7). Keep fresh oranges and yogurt refrigerated or at room temperature as appropriate; don't seal them inside hot freezer meal packs.</p>${checkHTML(`snack-${today()}-${day}`,'Fruit or snack packed / enjoyed')}</div><div class="card wide">${section('Ready to shop?','YOUR LIST HAS ITS OWN PAGE')}<p class="sub">Open the grocery checklist without scrolling past all your recipes.</p><button class="btn primary" onclick="go('grocery')">Open grocery list →</button></div><div class="card">${section('Monthly featured meal',`MONTH ${current().m} · JUST FOR FUN`)}<h3>${esc(featured)}</h3>${funRecipeDetails(current().m-1)}<p class="sub">One featured idea each month, in addition to your everyday meals. For packaged noodles, check the label for vegetarian ingredients; formulations vary. Optional pairing: Diet Pepsi with a scoop of vanilla ice cream.</p></div><div class="card">${section('Meal prep & food safety','PREP CHECKLIST')}${['Cook rice and lentils according to package directions.','Bake tofu and sweet potatoes; steam vegetables.','Prepare chili; cook eggs thoroughly when serving.','Divide cooked food into shallow, food-safe containers; refrigerate within 2 hours (within 1 hour above 90°F). Refrigerate up to 3–4 days, and freeze portions for later in the week.'].map((t,i)=>checkHTML(`prep-${current().m}-${current().w}-${i}`,esc(t))).join('')}<p class="note">Refrigerate within 2 hours at 40°F / 4°C or colder; eat refrigerated cooked leftovers within 3–4 days or freeze. Reheat leftovers to 165°F / 74°C.</p></div><div class="card wide">${section('Food journal','OPTIONAL REFLECTION')}<textarea oninput="saveMealNote(this.value)" placeholder="Meals, snacks, or ideas you want to remember">${esc(state.mealNotes[today()]||'')}</textarea><p class="note">Eat enough for your energy, growth, and recovery. This shopping budget is not a food limit.</p></div></div>`}

function saveMealNote(v){state.mealNotes[today()]=v;localSave()}
function planner(){return `<p class="sub">Explore all 12 months. Your PDF provides four checklist weeks per month, with room for extra calendar days. Choose your own pace and repeat a month when helpful.</p><div class="monthgrid">${MONTHS.map((m,i)=>`<button class="monthbtn ${month===i+1?'selected':''}" onclick="setMonth(${i+1})"><span class="eyebrow">MONTH</span><b>${String(i+1).padStart(2,'0')}</b><strong>${esc(m[0])}</strong></button>`).join('')}</div><div class="card" style="margin-top:18px">${section(MONTHS[month-1][0],`MONTH ${month} • ROADMAP`)}<p class="sub">${esc(MONTHS[month-1][1])}</p><div class="divider"></div><h3>Featured vegetarian meal</h3><p class="sub">${esc(FUN_MEALS[month-1])}</p>${funRecipeDetails(month-1)}<div class="divider"></div><h3>Four-week checklist</h3><div class="week weekhead">${['WK','M','T','W','T','F','S','S'].map(x=>`<label>${x}</label>`).join('')}</div>${[1,2,3,4].map(w=>`<div class="week"><label><b>${w}</b></label>${DAYS.map((d,i)=>`<label title="${d}"><input aria-label="Month ${month} week ${w} ${d}" type="checkbox" ${checked(`plan-${month}-${w}-${i}`)?'checked':''} onchange="setCheck('plan-${month}-${w}-${i}',this.checked)"></label>`).join('')}</div>`).join('')}${[1,2,3,4].map(w=>checkHTML(`plan-prep-${month}-${w}`,`Week ${w} meal prep completed`)).join('')}<div class="divider"></div><h3>Monthly check-in</h3>${[['push','Push-up variation / reps'],['jog','Comfortable walk/jog duration'],['strength','Strength or movement improvement'],['energy','Recovery and energy notes']].map(([k,l])=>`<div class="field"><label for="note-${k}">${l}</label><textarea id="note-${k}" oninput="saveNote('${month}-${k}',this.value)" placeholder="Write what feels useful to you...">${esc(state.notes[month+'-'+k]||'')}</textarea></div>`).join('')}<p class="note">A checkmark represents effort, not perfection. Rest and flexible scheduling count.</p></div>`}
function saveNote(k,v){state.notes[k]=v;localSave()}
function settings(){let cfg=state.config;return `<div class="grid"><div class="card">${section('Your plan','PERSONAL SETTINGS')}<div class="field"><label for="appearance">Appearance</label><select id="appearance" onchange="setAppearance(this.value)"><option value="light" ${appearanceChoice()==='light'?'selected':''}>Light (default)</option><option value="dark" ${appearanceChoice()==='dark'?'selected':''}>Dark — stays until changed</option><option value="automatic" ${appearanceChoice()==='automatic'?'selected':''}>Automatic — match device</option></select></div><div class="field"><label for="start">Start date</label><input type="date" id="start" value="${esc(state.start)}" onchange="state.start=this.value;localSave();render()"></div><p class="note">Changing your start date updates the suggested current month. Your checklist history remains intact.</p><button class="btn" onclick="exportBackup()">Download progress backup</button><div class="field"><label for="importFile">Restore a saved backup</label><input id="importFile" type="file" accept="application/json,.json" onchange="importBackup(this.files[0])"></div></div><div class="card">${section('Cloud sync','OPTIONAL SUPABASE CONNECTION')}<div class="notice">Cloud syncing is <b>not active until you connect your own Supabase project</b>. Your data is saved locally in this browser meanwhile. Never enter a service-role or secret key here—only a public publishable/anon key.</div><div class="field"><label for="url">Supabase project URL</label><input id="url" placeholder="https://your-project.supabase.co" value="${esc(cfg.url||'')}"></div><div class="field"><label for="key">Supabase publishable / anon key</label><input id="key" placeholder="sb_publishable_... or eyJ..." value="${esc(cfg.key||'')}"></div><button class="btn" onclick="saveConfig()">Save connection</button><div class="divider"></div><div class="field"><label for="email">Email</label><input id="email" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" placeholder="At least 8 characters"></div><div class="row" style="flex-wrap:wrap"><button class="btn primary" onclick="auth('login')">Sign in</button><button class="btn" onclick="auth('signup')">Create account</button><button class="btn" onclick="logout()">Sign out</button></div><p id="authMessage" class="note">${account?'Signed in: '+esc(account):'Not signed in.'}</p><p class="note">For security, your password is not saved in this app. Cloud sync uses your own account and database row-level security.</p></div><div class="card wide">${section('Install on your devices','FREE HOME-SCREEN APP')}<p class="sub">Once hosted on an HTTPS website, open it in your phone browser. On iPhone, use Share → Add to Home Screen. On Android, use the browser menu → Install app or Add to Home screen. On a computer, use the browser’s install option if available.</p><p class="note">The app shell can work offline after installation. Cloud sync requires internet. Illustrative food photographs are fetched online and may not appear offline. Local browser data can be cleared, so export backups regularly until cloud sync is configured.</p></div></div>`}
function saveConfig(){let url=$('#url').value.trim().replace(/\/$/,'');let key=$('#key').value.trim();if(url&&!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(url)){alert('Use your Supabase HTTPS project URL.');return}state.config={url,key};localSave();alert('Connection settings saved locally. Set up the SQL table and sign in to enable sync.')}
function exportBackup(){let blob=new Blob([JSON.stringify({format:'form-v2',state},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='form-progress-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function importBackup(file){if(!file)return;try{let data=JSON.parse(await file.text());if(data.format!=='form-v2'||!data.state||typeof data.state.checks!=='object')throw Error('Not a FORM. backup');if(!confirm('Replace your local progress with this backup?'))return;let cfg=state.config;state=data.state;state.config=cfg;localSave();render()}catch(e){alert('Unable to restore backup: '+e.message)}}
function apiBase(){const {url,key}=state.config;if(!url||!key)throw Error('First save your Supabase project URL and publishable key in Settings.');return {url,key}}
const SESSION_KEY='form-auth-v3';
function storeSession(j){
 token=j.access_token;refreshToken=j.refresh_token||refreshToken;
 account=j.user?.email||account;
 expiresAt=Date.now()+(Number(j.expires_in)||3600)*1000;
 localStorage.setItem(SESSION_KEY,JSON.stringify({token,refreshToken,account,expiresAt}));
 sessionStorage.removeItem('form-session');
}
async function refreshSession(){
 if(refreshPromise)return refreshPromise;
 refreshPromise=(async()=>{
  if(!refreshToken)throw Error('Please sign in again.');
  const {url,key}=apiBase();
  const r=await fetch(`${url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:refreshToken})});
  const j=await r.json();
  if(!r.ok||!j.access_token)throw Error(j.error_description||j.msg||j.message||'Please sign in again.');
  storeSession(j);return token;
 })();
 try{return await refreshPromise}finally{refreshPromise=null}
}
async function validToken(){
 if(!token&&!refreshToken)throw Error('Please sign in.');
 if(!token||Date.now()>=expiresAt-60000)await refreshSession();
 return token;
}
async function cloudFetch(path,options={}){
 const {url,key}=apiBase();
 let bearer=await validToken();
 const request=t=>fetch(url+path,{...options,headers:{...options.headers,apikey:key,Authorization:'Bearer '+t}});
 let r=await request(bearer);
 if(r.status===401){bearer=await refreshSession();r=await request(bearer)}
 return r;
}
async function auth(mode){try{
 const {url,key}=apiBase();let email=$('#email').value.trim(),password=$('#password').value;
 if(!email||password.length<8)throw Error('Enter your email and a password of at least 8 characters.');
 const r=await fetch(`${url}/auth/v1/${mode==='signup'?'signup':'token?grant_type=password'}`,{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});
 let j=await r.json();if(!r.ok)throw Error(j.msg||j.error_description||j.message||'Authentication failed');
 if(j.access_token){storeSession(j);await pullCloud();render();alert('Signed in. Cloud sync is connected.')}else alert('Account created. Check your email to confirm your address, then sign in.');
 }catch(e){alert(e.message)}}
async function logout(){
 try{if(token){const {url,key}=apiBase();await fetch(`${url}/auth/v1/logout`,{method:'POST',headers:{apikey:key,Authorization:'Bearer '+token}})}}catch(e){console.warn(e)}
 token=null;refreshToken=null;account=null;expiresAt=0;
 localStorage.removeItem(SESSION_KEY);sessionStorage.removeItem('form-session');syncMessage='Saved locally';render();
}
async function pullCloud(){if(!token&&!refreshToken)return;try{
 let r=await cloudFetch('/rest/v1/form_progress?select=data,updated_at&limit=1');
 if(!r.ok)throw Error((await r.text()).slice(0,220));
 let rows=await r.json();if(rows.length&&rows[0].data){const remote=rows[0].data;
 if(new Date(rows[0].updated_at).getTime()>new Date(state.updated).getTime()){
 let cfg=state.config;state={...state,...remote,config:cfg};localStorage.setItem(KEY,JSON.stringify(state))}}
 syncMessage='Cloud connected';updateSync();render();if(!rows.length)await pushCloud();
 }catch(e){syncMessage='Cloud error — local copy saved';updateSync();console.warn(e)}}
async function pushCloud(){if(!token&&!refreshToken)return;try{
 let userRes=await cloudFetch('/auth/v1/user');
 if(!userRes.ok)throw Error('Session expired. Sign in again.');
 let user=await userRes.json();let data={...state};delete data.config;
 let r=await cloudFetch('/rest/v1/form_progress?on_conflict=user_id',{method:'POST',headers:{'Content-Type':'application/json','Prefer':'resolution=merge-duplicates'},body:JSON.stringify({user_id:user.id,data,updated_at:state.updated})});
 if(!r.ok)throw Error((await r.text()).slice(0,180));syncMessage='Synced to cloud';updateSync();
 }catch(e){syncMessage='Sync error — local copy saved';updateSync();console.warn(e)}}
try{
 let session=JSON.parse(localStorage.getItem(SESSION_KEY)||'null');
 if(session&&session.refreshToken){
  token=session.token;refreshToken=session.refreshToken;account=session.account;expiresAt=session.expiresAt||0;
  syncMessage='Connecting…';setTimeout(pullCloud,300);
 }else if(sessionStorage.getItem('form-session')){
  // Older versions did not retain a refresh token; a one-time sign-in is needed.
  sessionStorage.removeItem('form-session');
 }
}catch(e){console.warn('Could not restore login',e)}
render();if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
